package com.bank.tick.store;

import java.lang.foreign.*;
import java.math.BigDecimal;

// Off-heap price buffer whose lifetime is owned by an Arena.
public class ArenaPriceBuffer {
    private final MemorySegment segment;  // bounds-checked, arena-owned
    private final long slots;

    public ArenaPriceBuffer(Arena arena, long slots) {
        this.slots = slots;
        this.segment = arena.allocate(slots * Long.BYTES);  // off-heap, freed on arena.close()
    }

    public void put(long index, BigDecimal rupees) {
        // Spatial bounds check: out-of-range throws, never corrupts memory.
        long paise = rupees.movePointRight(2).longValueExact();
        segment.setAtIndex(ValueLayout.JAVA_LONG, index, paise);  // throws if index out of range
    }

    public BigDecimal get(long index) {
        long paise = segment.getAtIndex(ValueLayout.JAVA_LONG, index);
        return BigDecimal.valueOf(paise, 2);
    }

    public MemorySegment segment() { return segment; }  // exposed to show post-close behavior
}
