// ─── File: ArenaDemo.java ───
package com.bank.tick;

import com.bank.tick.store.ArenaPriceBuffer;
import java.lang.foreign.*;
import java.math.BigDecimal;
import java.nio.ByteBuffer;
import java.util.logging.*;

public class ArenaDemo {
    private static final Logger log = Logger.getLogger(ArenaDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MemorySegment leaked;  // keep a reference to prove post-close access fails

        // DETERMINISTIC lifetime: try-with-resources frees off-heap memory on close.
        try (Arena arena = Arena.ofConfined()) {
            var prices = new ArenaPriceBuffer(arena, 2);
            prices.put(0, new BigDecimal("1000000.00"));   // Rajesh
            prices.put(1, new BigDecimal("250000.00"));    // Priya
            log.info(() -> "Arena Rajesh: Rs." + prices.get(0));
            log.info(() -> "Arena Priya : Rs." + prices.get(1));

            // Spatial bounds check: index 2 is out of range → throws, no corruption.
            try { prices.get(2); }
            catch (IndexOutOfBoundsException e) { log.warning("Bounds check caught out-of-range read"); }

            leaked = prices.segment();
        } // <-- arena.close(): ALL off-heap memory freed deterministically HERE

        // Temporal safety: accessing a segment AFTER its arena closed → IllegalStateException.
        try {
            leaked.getAtIndex(ValueLayout.JAVA_LONG, 0);
        } catch (IllegalStateException e) {
            log.warning("Temporal safety: access after arena close was blocked (not a crash)");
        }

        // Contrast: direct ByteBuffer — off-heap bytes freed only when GC reclaims
        // the wrapper (non-deterministic). No explicit free, no temporal invalidation.
        ByteBuffer direct = ByteBuffer.allocateDirect(16);
        direct.putLong(0, new BigDecimal("50000.00").movePointRight(2).longValueExact());
        log.info(() -> "Direct buffer value: Rs." + BigDecimal.valueOf(direct.getLong(0), 2)
                + " (freed later by Cleaner — timing not controlled)");
    }
}
